from datetime import datetime, timedelta

from . import db
from .config import PORTFOLIO


def _parse_pub(s: str | None) -> datetime | None:
    if not s:
        return None
    for fmt in ("%d-%b-%Y %H:%M:%S", "%d %b %Y %H:%M", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(s.strip(), fmt)
        except ValueError:
            continue
    return None


def build_digest(window_hours: int = 24, ticker: str | None = None) -> dict:
    cutoff = datetime.utcnow() - timedelta(hours=window_hours)
    with db.get_db() as conn:
        rows = conn.execute(
            """SELECT id, ticker, headline, subject, category, materiality, priority, pdf_url,
                      published_at, summary, rules_handled
               FROM announcements ORDER BY priority DESC, id DESC LIMIT 2000"""
        ).fetchall()
        watch = {r["key"]: bool(r["is_enabled"]) for r in conn.execute("SELECT key, is_enabled FROM watch_types")}
        renders = {}
        for r in conn.execute("SELECT announcement_id, kind, payload_json FROM renders"):
            renders.setdefault(r["announcement_id"], {})[r["kind"]] = r["payload_json"]

    material, routine = [], []
    seen = set()
    for r in rows:
        pub = _parse_pub(r["published_at"])
        if pub and pub < cutoff:
            continue
        if r["ticker"] not in PORTFOLIO or r["id"] in seen:
            continue
        seen.add(r["id"])
        item = {
            **dict(r),
            "watched": watch.get(r["category"], False),
            "renders": renders.get(r["id"], {}),
        }
        (material if r["materiality"] == "material" else routine).append(item)

    by_cat: dict[str, int] = {}
    for item in routine:
        by_cat[item["category"]] = by_cat.get(item["category"], 0) + 1

    total = len(material) + len(routine)
    rules_pct = round(100 * sum(1 for i in material + routine if i["rules_handled"]) / total, 1) if total else 0.0
    return {
        "window_hours": window_hours,
        "stats": {"total": total, "material": len(material), "routine": len(routine), "rules_pct": rules_pct},
        "routine_collapsed": {"by_category": by_cat, "items": routine},
        "material": material,
    }

import re
import time

from curl_cffi import requests as cr

BASE = "https://www.screener.in"
UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"

_slug_cache: dict[str, str] = {}


def _slug(ticker: str) -> str:
    if ticker in _slug_cache:
        return _slug_cache[ticker]
    s = cr.Session(impersonate="chrome124")
    r = s.get(f"{BASE}/company/{ticker}/consolidated/", headers={"User-Agent": UA}, timeout=30)
    if r.status_code == 200:
        _slug_cache[ticker] = ticker
        return ticker
    r2 = s.get(f"{BASE}/company/{ticker}/", headers={"User-Agent": UA}, timeout=30)
    if r2.status_code == 200:
        _slug_cache[ticker] = ticker
        return ticker
    raise RuntimeError(f"screener page not found for {ticker} (HTTP {r.status_code}/{r2.status_code})")


def fetch_company_html(ticker: str) -> str:
    slug = _slug(ticker)
    s = cr.Session(impersonate="chrome124")
    r = s.get(f"{BASE}/company/{slug}/consolidated/", headers={"User-Agent": UA}, timeout=30)
    if r.status_code != 200:
        raise RuntimeError(f"screener HTTP {r.status_code} for {ticker}")
    return r.text


def parse_documents(html: str) -> dict:
    """Extract annual reports + concall transcript links from the Documents section."""
    docs = {"annual_reports": [], "concalls": [], "results": []}
    sec = re.search(r'id="documents"(.*?)(?=<h2|$)', html, re.S)
    block = sec.group(1) if sec else html
    for m in re.finditer(r'href="(https?://[^"]+\.pdf[^"]*)"[^>]*>([^<]*)<', block):
        url, label = m.group(1), m.group(2).strip()
        low = (url + " " + label).lower()
        if "conc" in low or "transcript" in low or "call" in low:
            docs["concalls"].append({"url": url, "label": label})
        elif "annual report" in low or "integrated report" in low or "annualreport" in low:
            docs["annual_reports"].append({"url": url, "label": label})
    for m in re.finditer(r'href="(https?://[^"]*(?:bseindia\.com|nseindia\.com)[^"]*)"[^>]*>([^<]*(?:results|financial)[^<]*)<', block, re.I):
        docs["results"].append({"url": m.group(1), "label": m.group(2).strip()})
    seen = set()
    for k in docs:
        uniq = []
        for d in docs[k]:
            if d["url"] not in seen:
                seen.add(d["url"])
                uniq.append(d)
        docs[k] = uniq
    return docs


def parse_quarterly_table(html: str) -> dict:
    """Parse screener's Quarterly table (10 quarters) → {periods: [...], rows: {metric: [values]}}."""
    from bs4 import BeautifulSoup

    soup = BeautifulSoup(html, "lxml")
    out = {}
    for table in soup.find_all("table"):
        headers = [th.get_text(" ", strip=True) for th in table.find_all("th")]
        if not any("Sep 2026" in h or "Jun 2026" in h or "Sep 2025" in h for h in headers):
            continue
        body_headers = [h for h in headers if h and not h.isalpha() or " 20" in h]
        periods = [h for h in headers if re.match(r"^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{4}$", h)]
        if not periods:
            continue
        rows = {}
        for tr in table.find_all("tr"):
            tds = tr.find_all("td")
            if not tds:
                continue
            name = tds[0].get_text(" ", strip=True)
            vals = [td.get_text(" ", strip=True).replace(",", "") for td in tds[1:]]
            rows[name] = vals
        out["periods"] = periods
        out["rows"] = rows
        break
    return out


def parse_snapshot_metrics(html: str) -> dict:
    from bs4 import BeautifulSoup

    soup = BeautifulSoup(html, "lxml")
    top = {}
    for li in soup.select("ul#top-ratios li"):
        name_el = li.find("span", class_="name")
        num_el = li.find("span", class_="number")
        if name_el and num_el:
            top[name_el.get_text(strip=True)] = num_el.get_text(strip=True)
    return top


def fetch_all(ticker: str) -> dict:
    html = fetch_company_html(ticker)
    time.sleep(0.3)
    return {
        "ticker": ticker,
        "documents": parse_documents(html),
        "quarterly": parse_quarterly_table(html),
        "top_ratios": parse_snapshot_metrics(html),
    }

