input.content:
import json
import re

from . import db, llm, nse_client
from .config import BACKEND_DIR

FILINGS_DIR = BACKEND_DIR / "data" / "filings"
METRICS = ["Revenue", "EBITDA", "PBT", "PAT"]


def extract_pdf_text(url: str, ticker: str) -> tuple[str, list[str]]:
    dest = FILINGS_DIR / ticker / (url.split("/")[-1].split("?")[0] or "results.pdf")
    ok = nse_client.download_pdf(url, dest)
    if not ok:
        return "", []
    try:
        from pypdf import PdfReader

        reader = PdfReader(str(dest))
        pages = [(p.extract_text() or "") for p in reader.pages]
        return "\n".join(f"[[PAGE {i+1}]]\n{t}" for i, t in enumerate(pages)), pages
    except Exception:
        return "", []


def select_results_pages(pages: list[str]) -> list[int]:
    scores = []
    for i, t in enumerate(pages):
        tl = t.lower()
        s = 0
        for kw in ("financial results", "revenue from operations", "profit before tax", "profit after tax",
                   "profit for the period", "quarter ended", "statement of"):
            if kw in tl:
                s += 3
        if "ebitda" in tl or "depreciation" in tl:
            s += 2
        scores.append(s)
    if not scores or max(scores) == 0:
        return list(range(min(6, len(pages))))
    best = sorted(range(len(pages)), key=lambda i: -scores[i])[:4]
    return sorted(best)


def _num_ok(x) -> bool:
    return isinstance(x, (int, float)) and not isinstance(x, bool) and abs(x) < 1e9


def sanity_check(card: dict) -> bool:
    rows = card.get("rows") or []
    if not isinstance(rows, list) or len(rows) < 3:
        return False
    labels = {str(r.get("label", "")).lower() for r in rows}
    if not any("revenue" in l for l in labels):
        return False
    for r in rows:
        if not _num_ok(r.get("current")):
            return False
        for k in ("qoq", "yoy"):
            v = r.get(k)
            if v is not None and (not _num_ok(v) or abs(v) > 300):
                return False
    by_label = {str(r.get("label", "")).lower(): r for r in rows}
    pat = next((v for l, v in by_label.items() if "pat" in l or "net profit" in l), None)
    pbt = next((v for l, v in by_label.items() if "pbt" in l or "profit before tax" in l), None)
    if pat and pbt and pat.get("current") is not None and pbt.get("current") is not None:
        if pat["current"] > pbt["current"] * 1.05:
            return False
    return True


def build_results_card(ann_id: int, ticker: str, pdf_url: str, subject: str) -> dict | None:
    text, pages = extract_pdf_text(pdf_url, ticker)
    if not pages:
        return None
    page_idx = select_results_pages(pages)
    chunk = "\n".join(f"[[PAGE {i+1}]]\n{pages[i]}" for i in page_idx)[:14000]
    prompt = (
        "This is an Indian company's quarterly financial results filing (exchange filing). Extract the headline numbers.\n"
        "Return STRICT JSON: {\"period\": \"e.g. Q2 FY27 (Sep 2026 quarter)\", \"currency_unit\": \"Rs Cr|Rs L|Rs\", "
        "\"rows\": [{\"label\": \"Revenue|EBITDA|PBT|PAT\", \"current\": <num>, \"prev_quarter\": <num|null>, \"year_ago\": <num|null>}]}\n"
        "Rules: numbers in the filing's own unit (state it). EBITDA = profit before tax + finance cost + depreciation if EBITDA not stated. "
        "prev_quarter = the sequential comparison column; year_ago = the same-quarter-last-year column. Use null if a column is absent. "
        "Copy numbers EXACTLY as printed (do not convert units).\n\n" + chunk
    )
    data = llm.call_json("results_extract", prompt, tier="cheap")
    card = None
    if data and isinstance(data.get("rows"), list):
        card = _finalize(data, ticker, page_idx, "high")
        if card and sanity_check(card):
            return card
    strong = llm.call_json("results_extract_strong", prompt, tier="strong")
    if strong and isinstance(strong.get("rows"), list):
        card = _finalize(strong, ticker, page_idx, "strong-recheck")
        if card and sanity_check(card):
            return card
    return card if card and sanity_check(card) else None


def _finalize(data: dict, ticker: str, page_idx: list[int], confidence: str) -> dict | None:
    unit = data.get("currency_unit") or "Rs Cr"
    rows = []
    for r in data["rows"]:
        cur, pq, ya = r.get("current"), r.get("prev_quarter"), r.get("year_ago")
        if not _num_ok(cur):
            continue
        qoq = round(100 * (cur - pq) / abs(pq), 1) if _num_ok(pq) and pq != 0 else None
        yoy = round(100 * (cur - ya) / abs(ya), 1) if _num_ok(ya) and ya != 0 else None
        rows.append({"label": r.get("label", "?"), "current": cur, "qoq": qoq, "yoy": yoy})
    if not rows:
        return None
    src_page = (page_idx[0] + 1) if page_idx else None
    return {
        "ticker": ticker,
        "period": data.get("period", ""),
        "currency": unit,
        "rows": rows,
        "source": {"doc": "results filing", "page": str(src_page) if src_page else ""},
        "confidence": confidence,
    }


def enrich_results() -> int:
    n = 0
    with db.get_db() as conn:
        pending = conn.execute(
            """SELECT a.id, a.ticker, a.pdf_url, a.subject FROM announcements a
               LEFT JOIN renders r ON r.announcement_id = a.id AND r.kind = 'results_card'
               WHERE a.category = 'results' AND a.pdf_url IS NOT NULL AND a.pdf_url != '' AND r.id IS NULL
               ORDER BY a.priority DESC LIMIT 10"""
        ).fetchall()
    for row in pending:
        card = build_results_card(row["id"], row["ticker"], row["pdf_url"], row["subject"])
        if card:
            with db.get_db() as conn:
                conn.execute(
                    "INSERT OR IGNORE INTO renders (announcement_id, kind, payload_json) VALUES (?, 'results_card', ?)",
                    (row["id"], json.dumps(card)),
                )
            n += 1
    return n

import json

import httpx

from . import db, llm
from .config import TAVILY_API_KEY


def extract_person_role(subject: str) -> dict | None:
    out = llm.call_json(
        "bio_person_extract",
        "From this Indian exchange announcement, extract the incoming person. Return STRICT JSON "
        '{"person": "name or null", "role": "role/title or null", "is_incoming": true|false}. '
        "is_incoming=false if the announcement is about someone leaving/retiring with no named successor.\n\n"
        + subject[:800],
        tier="cheap",
    )
    if out and out.get("person") and out.get("is_incoming", True):
        return {"person": out["person"], "role": out.get("role") or ""}
    return None


def tavily_search(query: str) -> list[dict]:
    if not TAVILY_API_KEY:
        return []
    try:
        r = httpx.post(
            "https://api.tavily.com/search",
            json={"api_key": TAVILY_API_KEY, "query": query, "max_results": 5, "search_depth": "basic"},
            timeout=25,
        )
        r.raise_for_status()
        return r.json().get("results", [])
    except Exception:
        return []


def build_bio(subject: str) -> dict | None:
    who = extract_person_role(subject)
    if not who:
        return None
    query = f"{who['person']} {who['role']} appointment India background career".strip()
    results = tavily_search(query)
    if not results:
        return None
    content = "\n".join(f"- {r.get('title','')}: {r.get('content','')[:400]}" for r in results[:5])
    out = llm.call_json(
        "bio_summary",
        "Write a short professional bio (2-3 sentences, factual, neutral) of this person based ONLY on these search snippets. "
        'Return STRICT JSON: {"bio": "...", "source_query": "..."}\n'
        f"Person: {who['person']} | Role: {who['role']}\nSnippets:\n{content}",
        tier="cheap",
    )
    if not out or not out.get("bio"):
        return None
    return {"person": who["person"], "role": who["role"], "bio": out["bio"], "source_query": query}


def enrich_bios() -> int:
    n = 0
    with db.get_db() as conn:
        pending = conn.execute(
            """SELECT a.id, a.subject FROM announcements a
               LEFT JOIN renders r ON r.announcement_id = a.id AND r.kind = 'bio'
               WHERE a.category = 'management_change' AND r.id IS NULL
               ORDER BY a.priority DESC LIMIT 10"""
        ).fetchall()
    for row in pending:
        bio = build_bio(row["subject"] or "")
        if bio:
            with db.get_db() as conn:
                conn.execute(
                    "INSERT OR IGNORE INTO renders (announcement_id, kind, payload_json) VALUES (?, 'bio', ?)",
                    (row["id"], json.dumps(bio)),
                )
            n += 1
        else:
            with db.get_db() as conn:
                conn.execute(
                    "INSERT OR IGNORE INTO renders (announcement_id, kind, payload_json) VALUES (?, 'bio', ?)",
                    (row["id"], json.dumps({"bio": None})),
                )
    return n

import hashlib
import json
import re
import threading
from datetime import datetime, timedelta

from . import db, llm, nse_client, screener
from .config import BACKEND_DIR

FILINGS_DIR = BACKEND_DIR / "data" / "filings"
MAX_DOC_CHARS = 400_000
SECTIONS = [
    "business_snapshot", "financial_snapshot", "trajectory", "balance_sheet",
    "cash_quality", "narrative_vs_numbers", "guidance", "bull_vs_bear",
]


def _doc_id(url: str) -> str:
    return hashlib.sha1(url.encode()).hexdigest()[:16]


def _pdf_path(ticker: str, url: str):
    name = url.split("/")[-1].split("?")[0] or f"{_doc_id(url)}.pdf"
    return FILINGS_DIR / ticker / name


def _load_text(ticker: str, url: str) -> tuple[str, str]:
    """Returns (text_with_page_markers, period_label). Cached via filings table."""
    path = _pdf_path(ticker, url)
    with db.get_db() as conn:
        row = conn.execute("SELECT * FROM filings WHERE ticker = ? AND url = ?", (ticker, url)).fetchone()
    if row and row["path"] and (BACKEND_DIR / row["path"]).exists():
        text = (BACKEND_DIR / row["path"]).read_text(errors="ignore")
        return text, row["period"] or ""
    ok = nse_client.download_pdf(url, path)
    if not ok:
        return "", ""
    try:
        from pypdf import PdfReader

        pages = [(p.extract_text() or "") for p in PdfReader(str(path)).pages]
    except Exception:
        pages = []
    if not pages or sum(len(p) for p in pages) < 500:
        try:
            import pdfplumber

            with pdfplumber.open(str(path)) as pdf:
                pages = [(p.extract_text() or "") for p in pdf.pages]
        except Exception:
            pages = []
    text = "\n".join(f"[[PAGE {i+1}]]\n{t}" for i, t in enumerate(pages))[:MAX_DOC_CHARS]
    rel = path.relative_to(BACKEND_DIR)
    period = ""
    m = re.search(r"(20\d{2})", url.split("/")[-1])
    with db.get_db() as conn:
        conn.execute(
            """INSERT INTO filings (ticker, kind, url, period, path, content_hash) VALUES (?, ?, ?, ?, ?, ?)
               ON CONFLICT(ticker, kind, url) DO UPDATE SET path = excluded.path, content_hash = excluded.content_hash""",
            (ticker, "doc", url, period, str(rel), _doc_id(text or url)),
        )
    return text, period


def _extract_from_doc(ticker: str, kind: str, period: str, url: str) -> dict:
    text, _ = _load_text(ticker, url)
    if len(text) < 1000:
        return {"doc": kind, "period": period, "facts": [], "promises": [], "unavailable": True}
    doc_label = f"{kind} {period}".strip()
    prompt = (
        f"You are reading the {doc_label} of Indian listed company {ticker}. Text contains [[PAGE n]] markers.\n"
        "Extract, citing every item with the page number it came from:\n"
        '1. "facts": key business/financial facts (business model, segments, revenue mix, margins, debt, working capital, '
        "cash flow, capex, ROCE, auditor flags, contingent liabilities, related-party notes) — max 25, most decision-relevant.\n"
        '2. "promises": forward-looking commitments management makes (growth %, margin %, revenue targets, capex plans, '
        "order book, launches, timelines) — include the period it was said (e.g. Q2 FY27 call) — ALL you can find.\n"
        'Return STRICT JSON: {"facts": [{"topic": "...", "note": "...", "page": <int>}], '
        '"promises": [{"promise": "...", "metric": "...", "target": "...", "period_promised": "...", "page": <int>}]}\n'
        "Only include what is explicitly in the text. No outside knowledge.\n\n" + text
    )
    out = llm.call_json(f"research_extract:{ticker}:{doc_label}", prompt, tier="cheap")
    if not isinstance(out, dict):
        return {"doc": doc_label, "period": period, "facts": [], "promises": []}
    for f in out.get("facts", []):
        f["doc"] = doc_label
    for p in out.get("promises", []):
        p["doc"] = doc_label
    return {"doc": doc_label, "period": period, "facts": out.get("facts", []), "promises": out.get("promises", [])}


def _quarterly_actuals(screener_data: dict) -> dict:
    q = screener_data.get("quarterly") or {}
    periods, rows = q.get("periods") or [], q.get("rows") or {}
    last = periods[-8:] if len(periods) > 8 else periods
    out = {"periods": last}
    for name, vals in rows.items():
        out[name] = vals[-8:] if len(vals) > 8 else vals
    return out


def _synthesise(ticker: str, name: str, extractions: list[dict], actuals: dict, top_ratios: dict) -> dict:
    facts = []
    promises = []
    for e in extractions:
        facts.extend(e.get("facts", []))
        promises.extend(e.get("promises", []))
    facts_json = json.dumps(facts[:80], ensure_ascii=False)
    promises_json = json.dumps(promises[:60], ensure_ascii=False)
    actuals_json = json.dumps(actuals, ensure_ascii=False)
    prompt = (
        f"Build an investment research dossier for {ticker} ({name}) STRICTLY from the primary-source material below "
        "(facts extracted from its annual report + concall transcripts, and standardized quarterly actuals from filings). "
        "No outside knowledge, no news.\n\n"
        f"QUARTERLY ACTUALS (screener-standardized, Rs Cr unless stated):\n{actuals_json}\n\n"
        f"SNAPSHOT RATIOS: {json.dumps(top_ratios, ensure_ascii=False)}\n\n"
        f"FACTS FROM PRIMARY DOCS (each has doc + page):\n{facts_json}\n\n"
        f"MANAGEMENT PROMISES FROM TRANSCRIPTS (each has doc + period + page):\n{promises_json}\n\n"
        'Return STRICT JSON with keys:\n'
        '{"sections": {'
        '"business_snapshot": {"title": "...", "text": "...", "citations": [{"doc","period","page"}]}, '
        '"financial_snapshot": {...}, "trajectory": {...}, "balance_sheet": {...}, "cash_quality": {...}, '
        '"narrative_vs_numbers": {...}, "guidance": {...}, "bull_vs_bear": {...}}, '
        '"promise_tracker": {"rows": [{"period_promised", "promise", "metric", "target", "delivered", '
        '"verdict": "delivered|missed|partial|unverifiable", "citations": [{"doc","period","page"}]}]}}\n\n'
        "Rules: every citation must reference a doc+page present in the material. In promise_tracker, 'delivered' must quote "
        "or compute from QUARTERLY ACTUALS only; verdict 'unverifiable' if actuals don't cover it. Sections: concise, "
        "bullet-friendly, 80-150 words each. bull_vs_bear: two tight cases."
    )
    out = llm.call_json(f"research_synthesis:{ticker}", prompt, tier="strong")
    return out if isinstance(out, dict) else {}


def _finish_report(ticker: str) -> dict:
    data = screener.fetch_all(ticker)
    docs = data.get("documents") or {}
    concalls = sorted(docs.get("concalls", []), key=lambda d: d.get("period", ""), reverse=True)[:4]
    ars = sorted(docs.get("annual_reports", []), key=lambda d: d.get("period", ""), reverse=True)[:1]
    name = ""
    extractions = []
    sources = []
    for c in concalls:
        e = _extract_from_doc(ticker, "Concall", c.get("period", ""), c["url"])
        extractions.append(e)
        sources.append({"kind": "Concall", "period": c.get("period", ""), "url": c["url"]})
    for a in ars:
        e = _extract_from_doc(ticker, "Annual Report", a.get("period", a.get("label", "")), a["url"])
        extractions.append(e)
        sources.append({"kind": "Annual Report", "period": a.get("period", a.get("label", "")), "url": a["url"]})
    actuals = _quarterly_actuals(data)
    ratios = data.get("top_ratios") or {}
    name = ratios.get("High / Low", "") and ticker or ticker
    report = _synthesise(ticker, name, extractions, actuals, ratios)
    if not report or "sections" not in report:
        raise RuntimeError("synthesis failed")
    sections = {k: v for k, v in report.get("sections", {}).items() if k in SECTIONS}
    rows = report.get("promise_tracker", {}).get("rows", [])
    cited_rows = [r for r in rows if r.get("citations") and len(r["citations"]) > 0]
    return {
        "ticker": ticker,
        "name": name or ticker,
        "generated_at": datetime.utcnow().isoformat(timespec="seconds"),
        "sections": sections,
        "promise_tracker": {"rows": cited_rows},
        "sources": sources,
    }


def get_status(ticker: str) -> dict:
    with db.get_db() as conn:
        row = conn.execute("SELECT * FROM research_reports WHERE ticker = ?", (ticker.upper(),)).fetchone()
    if not row:
        return {"status": "missing"}
    if row["payload_json"]:
        try:
            return {"status": "done", "report": json.loads(row["payload_json"])}
        except ValueError:
            pass
    return {"status": row["status"]}


def start(ticker: str) -> dict:
    t = ticker.upper()
    st = get_status(t)
    if st["status"] == "done":
        with db.get_db() as conn:
            row = conn.execute("SELECT expires_at FROM research_reports WHERE ticker = ?", (t,)).fetchone()
        if row and row["expires_at"] and row["expires_at"] > datetime.utcnow().isoformat(timespec="seconds"):
            return {"status": "done", "report": st["report"]}
    with db.get_db() as conn:
        conn.execute(
            """INSERT INTO research_reports (ticker, status) VALUES (?, 'pending')
               ON CONFLICT(ticker) DO UPDATE SET status = 'pending', payload_json = NULL, generated_at = NULL""",
            (t,),
        )
    threading.Thread(target=_worker, args=(t,), daemon=True).start()
    return {"status": "pending"}


def _worker(ticker: str) -> None:
    try:
        report = _finish_report(ticker)
        expires = (datetime.utcnow() + timedelta(hours=24)).isoformat(timespec="seconds")
        with db.get_db() as conn:
            conn.execute(
                "UPDATE research_reports SET status = 'done', payload_json = ?, generated_at = ?, expires_at = ? WHERE ticker = ?",
                (json.dumps(report, ensure_ascii=False), report["generated_at"], expires, ticker),
            )
    except Exception as e:
        with db.get_db() as conn:
            conn.execute(
                "UPDATE research_reports SET status = 'error', payload_json = ? WHERE ticker = ?",
                (json.dumps({"error": str(e)[:300]}), ticker),
            )

