const { chromium } = require("playwright");

const BASE = "http://localhost:3000";
const OUT = "/home/thakr/projects/finn/docs/screens";
const PAGES = [
  ["today", "/"],
  ["radar", "/alerts"],
  ["research", "/research"],
  ["research-irctc", "/research?demo=IRCTC"],
  ["settings", "/settings"],
];

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  for (const [name, path] of PAGES) {
    try {
      await page.goto(BASE + path, { waitUntil: "networkidle", timeout: 20000 });
    } catch (e) {}
    await page.waitForTimeout(1500);
    if (name === "research-irctc") {
      const chip = await page.$("button.chip, button");
      await page.screenshot({ path: `${OUT}/before-${name}.png`, fullPage: false });
      continue;
    }
    await page.screenshot({ path: `${OUT}/before-${name}.png`, fullPage: false });
    await page.screenshot({ path: `${OUT}/before-${name}-full.png`, fullPage: true });
    console.log("shot", name);
  }
  await browser.close();
})();

