};

export type BioCard = {
  person: string;
  role: string;
  bio: string;
  sources?: string[];
  source_type?: "filing" | "web" | "none";
};

export type Alert = {
  id: number;
  ticker: string;
  type: "material" | "volume" | "price";
  payload: Record<string, number | string>;
  severity: string;
  created_at: string;
};

export type Bars = {
  ticker: string;
  bars: { date: string; close: number; volume: number }[];
  avg20_volume: number | null;
};

export type Preview = {
